  const index = Math.round(rail.scrollLeft / ((rail.firstElementChild?.offsetWidth || 1) + 12))
  section.querySelectorAll('.card-rail__dot').forEach((dot, i) => dot.classList.toggle('card-rail__dot--active', i === index))
