// An invitation's TTL is not proof that its tournament still accepts players.
// Missing preview fields are tolerated for legacy responses and SSE deltas.
function bmtOct7_inviteTime(value) {
  if (!value) return NaN
  const text = String(value)
  return Date.parse(/(?:Z|[+-]\d{2}(?::?\d{2})?)$/i.test(text) ? text : `${text}Z`)
}

function bmtOct7_unavailableInviteReason(invite, tournament = invite?.tournament_preview, now = Date.now()) {
  const status = String(invite?.status || '').toUpperCase()
  if (status !== 'PENDING') return status === 'ACCEPTED' ? 'already_accepted' : 'invalid_state'
  const poolStatus = String(tournament?.status || '').toUpperCase()
  if (poolStatus === 'COMPLETED' || bmtOct7_inviteTime(tournament?.window_end_time) <= now) return 'tournament_ended'
  if (poolStatus === 'LOCKED') return 'tournament_locked'
  if (poolStatus && poolStatus !== 'UPCOMING') return 'tournament_unavailable'
  if (bmtOct7_inviteTime(invite.expires_at) <= now) return 'expired'
  const entities = tournament?.entities
  const count = entities?.count ?? entities?.guids?.length ?? 0
  if (Number(entities?.max) > 0 && count >= Number(entities.max)) return 'pool_full'
  return null
}

function bmtOct7_inviteAcceptFailure(response) {
  let code = response?.data?.error || `http_${response?.status || 0}`
  const status = String(response?.data?.status || '').toUpperCase()
  if (['invalid_state', 'invalid_tournament_state', 'tournament_unavailable'].includes(code)) {
    if (status === 'COMPLETED') code = 'tournament_ended'
    else if (status === 'LOCKED') code = 'tournament_locked'
    else if (status === 'ACCEPTED') code = 'already_accepted'
    else if (status === 'POOL_FULL') code = 'pool_full'
    else if (status === 'EXPIRED') code = 'expired'
  }
  const messages = {
    tournament_ended: 'This pool has ended. The invitation is no longer available.',
    tournament_locked: 'This pool is locked and no longer accepts players.',
    tournament_unavailable: 'This pool is no longer available to join.',
    invalid_tournament_state: 'This pool is no longer available to join.',
    tournament_not_found: 'This pool is no longer available. The invitation has been removed.',
    pool_full: 'This pool is full and no longer has an open spot.',
    expired: 'This invitation has expired. Ask the host for a new invite if the pool is still open.',
    already_accepted: 'You already joined this pool.',
    not_invitee: 'This invitation belongs to a different account.',
    invite_not_found: 'This invitation is no longer available. The host may have withdrawn it.',
    invalid_state: 'This invitation is no longer available.',
  }
  if (messages[code]) return { message: messages[code], terminal: true }
  if (response?.status === 401) return { message: 'Your session has expired. Sign in again to accept this invitation.', terminal: false }
  if (response?.status === 429) return { message: 'Too many attempts. Wait a moment before accepting again.', terminal: false }
  return { message: 'Couldn’t connect to join this pool. Your invitation is still here; please try again.', terminal: false }
}

