function ld(sheet, view = window, options = {}) {
  const {heightProperty = '--host-visible-height', topProperty = '--host-viewport-top',
    scrollerSelector = '.hm-sheet__scroll', compactAttribute = null, compactHeight = 450, keyboardClass = null, keyboardScrollerSelector = null} = options
  const viewport = view.visualViewport
  if (!viewport) return () => {}
  let frame = null
  let unfocusedHeight = viewport.height
  const sync = () => {
    frame = null
    if (viewport.height <= 0) return
    sheet.style.setProperty(heightProperty, `${viewport.height}px`)
    sheet.style.setProperty(topProperty, `${viewport.offsetTop}px`)
    if (compactAttribute) sheet.setAttribute(compactAttribute, String(viewport.height < compactHeight))
    // Singles use shadow-root inputs; the document's active element is their host.
    const host = sheet.ownerDocument.activeElement
    let active = host
    while (active?.shadowRoot?.activeElement) active = active.shadowRoot.activeElement
    const editing = sheet.contains(host) && active?.matches('input,textarea,select')
    const layoutHeight = view.document?.documentElement?.clientHeight || viewport.height
    if (!editing && layoutHeight - viewport.height < 120) unfocusedHeight = viewport.height
    const keyboard = editing && Math.max(layoutHeight, unfocusedHeight) - viewport.height > 120
    if (keyboardClass) sheet.classList.toggle(keyboardClass, !!keyboard)
    if (!editing) return
    const scroller = sheet.querySelector(keyboard && keyboardScrollerSelector ? keyboardScrollerSelector : scrollerSelector)
    if (!scroller || (scroller.contains && !scroller.contains(host))) return
    const area = scroller.getBoundingClientRect()
    const form = active.closest('form') || active
    let target = form.getBoundingClientRect()
    if (target.height > area.height - 24) target = active.getBoundingClientRect()
    if (target.bottom > area.bottom - 12) scroller.scrollTop += target.bottom - area.bottom + 12
    else if (target.top < area.top + 12) scroller.scrollTop -= area.top + 12 - target.top
  }
  const schedule = () => { if (frame === null) frame = view.requestAnimationFrame(sync) }
  viewport.addEventListener('resize', schedule)
  viewport.addEventListener('scroll', schedule)
  sheet.addEventListener('focusin', schedule)
  sheet.addEventListener('focusout', schedule)
  view.addEventListener?.('resize', schedule)
  sync()
  return () => {
    viewport.removeEventListener('resize', schedule)
    viewport.removeEventListener('scroll', schedule)
    sheet.removeEventListener('focusin', schedule)
    sheet.removeEventListener('focusout', schedule)
    view.removeEventListener?.('resize', schedule)
    if (keyboardClass) sheet.classList.remove(keyboardClass)
    if (frame !== null) view.cancelAnimationFrame(frame)
    sheet.style.removeProperty(heightProperty)
    sheet.style.removeProperty(topProperty)
    if (compactAttribute) sheet.removeAttribute(compactAttribute)
  }
}

